public static void check(Solution solution) {
    assert Arrays.equals(solution.equationsPossible(new int[]{"a!=a"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","c==d","e==f","g==h"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"c==c","b==d","x!=z"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","b==c","a!=c"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==a","b==b","c==c"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","b!=a","a==c","c==b"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a!=b","b!=c","c!=a"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a!=b","b!=c","a!=c"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","b!=c","c==a"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"b==a","a==b"}), True);
    assert Arrays.equals(solution.equationsPossible(new int[]{"f==g","g==f","f!=g"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","b!=a"}), False);
    assert Arrays.equals(solution.equationsPossible(new int[]{"a==b","b==c","a==c"}), True);
